<div class="top"><div><h2 style="margin:0">Supplier bills</h2><span class="muted">We owe <b class="<?= $owed > 0 ? 'overdue' : '' ?>"><?= e(money($owed)) ?></b> on open bills.</span></div><a class="btn" href="/staff/bills/new">+ New bill</a></div>
