<?php foreach ($rows as $b): $od = $b['status'] === 'open' && $b['due_date'] < date('Y-m-d'); ?><tr><td><?= e($b['sname']) ?></td><td><a href="/staff/bills/<?= (int) $b['id'] ?>"><?= e($b['bill_no']) ?></a></td><td><?= e(fmt_date($b['bill_date'])) ?></td><td class="<?= $od ? 'overdue' : '' ?>"><?= e(fmt_date($b['due_date'])) ?><?= $od ? ' (overdue)' : '' ?></td><td class="right"><?= e(money($b['amount'])) ?></td><td class="right"><?= e(money($b['paid'])) ?></td><td><?= badge($b['status'] === 'paid' ? 'Paid' : ($b['paid'] > 0 ? 'Part paid' : 'Open'), $b['status'] === 'paid' ? 'p-ok' : 'p-warn') ?></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="7" class="muted">No bills.</td></tr><?php endif; ?></table></div></div>
